#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}
/* Coupon launch layout: preserve Blogger native post rendering. */
body{background:#f6f7f9!important;color:#16202c!important}.bg-photo,.bg-photo-overlay{display:none!important}.centered-top-container{background:#fff!important}.Header h1{font-size:30px!important}.post-title{font-size:25px!important}.post-body{font-size:16px!important;line-height:1.8!important}.post-body a{color:#2259cc}.post-outer{border-radius:16px!important}.post-body section{margin:22px 0;padding:18px;border:1px solid #e5e7eb;border-radius:12px}.post-body table{display:block;max-width:100%;overflow-x:auto}.post-body img{max-width:100%;height:auto}@media(max-width:600px){.post-body{font-size:15px!important}.post-title{font-size:22px!important}.post-body section{padding:12px}.centered{max-width:100%!important}}
/* R3 coupon shell; native Blogger widgets remain intact. */
:root{--ncp-ink:#172033;--ncp-blue:#2457d6;--ncp-line:#e2e8f0}
body{margin:0!important;padding:0!important;background:#f4f6f8!important}.centered-top-container,.centered-top-placeholder,.sidebar-container,.bg-photo,.bg-photo-overlay{display:none!important}.page_body{padding-top:0!important}.centered{padding-top:0!important;max-width:1180px!important}.ncp-home .page{display:none!important}
.ncp-r3{font-family:Arial,'Noto Sans KR',sans-serif;color:var(--ncp-ink)}.ncp-r3 a{text-decoration:none;color:var(--ncp-blue)}.ncp-r3-wrap{max-width:1180px;margin:auto;padding:24px}.ncp-r3-header{background:#fff;border-bottom:1px solid var(--ncp-line)}.ncp-r3-head{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.ncp-r3-logo{font-size:26px;font-weight:800}.ncp-r3-search{display:flex;flex:1;min-width:240px;gap:8px}.ncp-r3 input{flex:1;min-width:0;padding:13px;border:1px solid var(--ncp-line);border-radius:10px}.ncp-r3 button,.ncp-r3-link{min-height:44px;padding:12px 16px;border:0;border-radius:10px;background:var(--ncp-blue);color:white!important;font-weight:700;cursor:pointer}.ncp-r3-rail{display:flex;gap:8px;overflow-x:auto;padding-top:0}.ncp-r3-chip{white-space:nowrap;padding:10px 14px;background:#edf2ff;border-radius:22px;font-size:14px}.ncp-r3-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.ncp-r3-card{padding:24px;border:1px solid var(--ncp-line);border-radius:16px;background:white;min-width:0}.ncp-r3 h1{font-size:36px;line-height:1.3}.ncp-r3 h2{margin:28px 0 16px;font-size:24px}.ncp-r3 h3{font-size:20px}.ncp-r3 p{line-height:1.8}.ncp-r3 code{display:block;padding:16px;background:#edf2ff;border-radius:10px;font-size:22px;overflow-wrap:anywhere}.ncp-r3-badge{display:inline-block;padding:6px 10px;background:#e8f6ed;border-radius:8px;font-size:13px}.ncp-r3-muted{color:#64748b;font-size:14px}.ncp-r3-footer{border-top:1px solid var(--ncp-line);margin-top:32px;background:white}.ncp-r3-copy-state{min-height:24px}.ncp-r3-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}
.ncp-feed-preview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:12px 0 6px}.ncp-feed-stat{min-width:0;padding:12px 14px;border:1px solid var(--ncp-line);border-radius:10px;background:#f8fafc}.ncp-feed-stat span{display:block;margin-bottom:3px;color:#64748b;font-size:12px;font-weight:700}.ncp-feed-stat strong{display:block;color:#172033;font-size:15px;line-height:1.45;overflow-wrap:anywhere}.ncp-feed-preview-generic .ncp-feed-stat strong{font-size:14px}
@media(max-width:700px){.ncp-feed-preview{grid-template-columns:1fr;gap:8px}.ncp-r3-wrap{padding:16px}.ncp-r3-grid{grid-template-columns:1fr}.ncp-r3 h1{font-size:28px}.ncp-r3-head{gap:16px}.ncp-r3-search{flex-basis:100%}.ncp-r3-card{padding:18px}.ncp-r3-rail{padding-top:0}.centered{padding:0!important}}
/* 구현 예시. 실제 테마 selector/변수와 충돌 여부 확인. */
.ncp-game-grid{
  --ncp-game-cols:4;
  --ncp-game-gap:10px;
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:var(--ncp-game-gap);
  width:100%;
  margin:0 auto;
}
.ncp-game-card{
  flex:0 0 calc((100% - (var(--ncp-game-gap) * (var(--ncp-game-cols) - 1))) / var(--ncp-game-cols));
  min-width:0;
  display:flex;
  flex-direction:column;
  align-items:center;
  text-align:center;
  text-decoration:none;
  box-sizing:border-box;
  padding:8px 2px 10px;
}
.ncp-game-icon-wrap{display:block;width:60px;aspect-ratio:1/1;overflow:hidden;border-radius:14px}
.ncp-game-icon{display:block;width:100%;height:100%;object-fit:cover}
.ncp-game-name{display:-webkit-box;margin-top:7px;max-width:100%;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;font-size:12px;line-height:1.25;word-break:keep-all}
.ncp-game-updated{margin-top:3px;font-size:10px;line-height:1.2;opacity:.64}
.ncp-game-card:focus-visible{outline:2px solid currentColor;outline-offset:3px}
@media (min-width:480px){.ncp-game-grid{--ncp-game-cols:5;--ncp-game-gap:12px}.ncp-game-icon-wrap{width:64px}.ncp-game-name{font-size:13px}.ncp-game-updated{font-size:11px}}
@media (min-width:768px){.ncp-game-grid{--ncp-game-cols:6;--ncp-game-gap:14px}.ncp-game-icon-wrap{width:68px}}
@media (min-width:1024px){.ncp-game-grid{--ncp-game-cols:7;--ncp-game-gap:16px}.ncp-game-icon-wrap{width:76px}.ncp-game-name{font-size:14px}}
@media (min-width:1280px){.ncp-game-grid{--ncp-game-cols:8;--ncp-game-gap:18px}.ncp-game-icon-wrap{width:82px}}
/* Selected bright marketplace home. */
.ncp-home{background:#fff!important}.ncp-r4{font-family:Arial,'Noto Sans KR',sans-serif;color:#142346}.ncp-r4-wrap{max-width:1240px;margin:auto;padding:24px}.ncp-r4-top{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid #edf1f7}.ncp-r4-logo{font-size:28px;font-weight:900;color:#1958df!important;text-decoration:none}.ncp-r4-top p{font-size:14px;color:#67788e}.ncp-r4-hero{background:#f4f8ff}.ncp-r4-hero-inner{display:grid;grid-template-columns:1.5fr 1fr;align-items:center;gap:24px;padding-top:32px;padding-bottom:32px}.ncp-r4-eyebrow{color:#245adf;font-weight:700;font-size:15px}.ncp-r4 h1{font-size:38px;line-height:1.35;letter-spacing:-1.5px;margin:12px 0 20px}.ncp-r4-search{display:flex;background:#fff;border:1px solid #cbd9f5;border-radius:12px;padding:6px;gap:8px}.ncp-r4-search input{width:100%;min-width:0;border:0;padding:12px;font-size:16px;background:transparent}.ncp-r4 button,.ncp-r4-button{border:0;border-radius:8px;background:#1858e9;color:#fff!important;padding:12px 20px;font-size:14px;font-weight:700;text-decoration:none;cursor:pointer;min-height:44px}.ncp-r4-hero img{width:100%;max-height:270px;object-fit:contain}.ncp-r4-sub{font-size:14px;color:#65738a;margin:12px 0 0}.ncp-r4-categories{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:14px;padding-top:24px;padding-bottom:20px}.ncp-r4-category{text-align:center;text-decoration:none;color:#233956!important;font-size:13px;font-weight:700;min-width:0}.ncp-r4-category span{display:flex;align-items:center;justify-content:center;height:70px;background:#f3f7fd;border-radius:15px;margin-bottom:9px}.ncp-r4-category:nth-child(3n+2) span{background:#f0fafb}.ncp-r4-category:nth-child(3n) span{background:#fff4f1}.ncp-r4-category img{width:38px;height:38px}.ncp-r4-section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin:12px 0 16px}.ncp-r4 h2{font-size:25px;letter-spacing:-.7px;margin:0}.ncp-r4-section-head a{font-size:14px;text-decoration:none;color:#1858e9}.ncp-r4-game-list{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px}.ncp-r4-card{border:1px solid #e4eaf4;border-radius:14px;overflow:hidden;background:#fff;min-width:0;transition:transform .15s,box-shadow .15s}.ncp-r4-card:hover{transform:translateY(-3px);box-shadow:0 8px 24px #14234612}.ncp-r4-cover{display:block;width:100%;height:150px;object-fit:cover;background:#f2f6fc}.ncp-r4-card-body{padding:15px}.ncp-r4-card h3{font-size:17px;line-height:1.45;margin:0 0 8px;overflow-wrap:anywhere}.ncp-r4-card p{font-size:12px;color:#697a92;line-height:1.6;margin:0 0 12px}.ncp-r4-card a{color:#142346;text-decoration:none}.ncp-r4-card .ncp-r4-detail{display:block;text-align:center;padding:10px;border-radius:8px;background:#edf3ff;color:#1858e9;font-size:13px;font-weight:700;min-height:20px}.ncp-r4-latest-list{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.ncp-r4-latest-list .ncp-r4-cover{height:100px;object-fit:contain;padding:12px;box-sizing:border-box}.ncp-r4-status{font-size:14px;color:#67788e}.ncp-r4-bottom{margin-top:28px;border-top:1px solid #e6edf5;display:flex;justify-content:space-between;align-items:center;gap:20px;font-size:13px;color:#67788e}.ncp-r4-bottom a{color:#1858e9}.ncp-r4 a:focus-visible,.ncp-r4 button:focus-visible,.ncp-r4 input:focus-visible{outline:3px solid #6d9eff;outline-offset:3px}
@media(max-width:900px){.ncp-r4-categories{grid-template-columns:repeat(5,minmax(0,1fr))}.ncp-r4-game-list{grid-template-columns:repeat(3,minmax(0,1fr))}.ncp-r4-latest-list{grid-template-columns:repeat(3,minmax(0,1fr))}.ncp-r4 h1{font-size:30px}}
@media(max-width:600px){.ncp-r4-wrap{padding:18px}.ncp-r4-top p{display:none}.ncp-r4-logo{font-size:25px}.ncp-r4-hero-inner{grid-template-columns:1fr;gap:8px}.ncp-r4-hero img{height:170px;grid-row:1}.ncp-r4 h1{font-size:27px;letter-spacing:-1px}.ncp-r4-eyebrow{font-size:13px}.ncp-r4-categories{gap:14px 7px}.ncp-r4-category{font-size:11px}.ncp-r4-category span{height:54px;border-radius:12px}.ncp-r4-category img{width:30px;height:30px}.ncp-r4-game-list,.ncp-r4-latest-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ncp-r4-cover{height:130px}.ncp-r4-card-body{padding:12px}.ncp-r4-card h3{font-size:15px}.ncp-r4 h2{font-size:22px}.ncp-r4-bottom{align-items:flex-start;flex-direction:column}.ncp-r4-search button{padding:12px 16px}}

.ncp-r4-search button{flex:none;white-space:nowrap;min-width:72px}.ncp-r4-card{display:flex;flex-direction:column}.ncp-r4-card-body{display:flex;flex-direction:column;flex:1}.ncp-r4-card .ncp-r4-detail{margin-top:auto}

/* Category pages share the selected home visual system. */
.ncp-r4-category-header{background:#fff;border-bottom:1px solid #edf1f7}.ncp-r4-category-header .ncp-r4-search{flex:1;max-width:800px}.ncp-category-page{background:#fff!important}.ncp-category-page .status-msg-wrap,.ncp-category-page .status-msg-body,.ncp-category-page .status-msg-border{display:none!important}
#ncp-game-hub{max-width:1240px;margin:auto;padding:24px;box-sizing:border-box}#ncp-game-hub h1{font-size:30px;margin:0 0 26px;color:#142346}.ncp-category-page .centered{max-width:1240px!important}
#ncp-game-hub .ncp-game-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:18px;justify-content:initial}#ncp-game-hub .ncp-game-card{padding:0;border:1px solid #e4eaf4;border-radius:14px;overflow:hidden;background:#fff;transition:transform .15s;align-items:stretch;text-align:left;color:#142346}#ncp-game-hub .ncp-game-card:hover{transform:translateY(-3px)}#ncp-game-hub .ncp-game-icon-wrap{width:100%;height:150px;aspect-ratio:auto;border-radius:0;background:#f3f7fc}#ncp-game-hub .ncp-game-name{margin:14px 14px 5px;font-size:16px;line-height:1.5}#ncp-game-hub .ncp-game-updated{margin:0 14px 16px;font-size:12px;color:#697a92;opacity:1}#ncp-game-hub [role='status']{padding:16px;background:#f5f8fd;border-radius:12px;color:#65738a}#ncp-game-hub [role='status']:empty{display:none}
@media(max-width:900px){#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:600px){.ncp-r4-category-header .ncp-r4-top{flex-wrap:wrap}.ncp-r4-category-header .ncp-r4-search{flex-basis:100%}#ncp-game-hub{padding:18px}#ncp-game-hub h1{font-size:25px}#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}#ncp-game-hub .ncp-game-icon-wrap{height:140px}#ncp-game-hub .ncp-game-name{font-size:14px}}

.ncp-category-page .page_body{margin-left:0!important;margin-right:0!important}
.ncp-category-page .centered{margin:0 auto!important;width:100%!important;max-width:1288px!important;box-sizing:border-box}.ncp-category-page .post-filter-message{display:none!important}.ncp-category-page .centered-bottom{padding:0!important}
.ncp-category-page #ncp-game-hub{max-width:none;width:100%;box-sizing:border-box}
.item-view .page_body{margin-left:0!important;margin-right:0!important}
.item-view .centered{margin:0 auto!important;width:100%!important;max-width:1288px!important;box-sizing:border-box}


/* White veil game cards: real current coupon counts. */
.ncp-game-visual{position:relative;background:#fff!important}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-cover,#ncp-game-hub .ncp-game-visual .ncp-game-icon{opacity:.23;filter:blur(1.5px);transform:scale(1.03)}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3{position:absolute;top:75px;left:14px;right:14px;transform:translateY(-50%);margin:0;text-align:center;font-size:19px;line-height:1.4;font-weight:800;z-index:2;text-shadow:0 1px 5px #fff}
#ncp-game-hub .ncp-game-visual .ncp-game-icon-wrap{position:relative;overflow:hidden;background:#fff}
#ncp-game-hub .ncp-game-visual .ncp-game-name{position:absolute;top:50%;left:14px;right:14px;transform:translateY(-50%);margin:0;text-align:center;font-size:19px;line-height:1.4;font-weight:800;color:#142346;z-index:2;text-shadow:0 1px 5px #fff}
.ncp-coupon-count{position:absolute;top:10px;left:10px;z-index:3;display:inline-flex;align-items:center;padding:5px 9px;border-radius:8px;background:#2457d6;color:#fff;font-size:12px;font-weight:800;line-height:1.4;box-shadow:0 2px 6px #14234615}
#ncp-game-hub .ncp-game-visual .ncp-game-updated{margin-top:12px}
@media(max-width:600px){.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{font-size:17px;left:10px;right:10px}}

/* Keep artwork sharp; blur only the background behind the game name. */
.ncp-r4-game-list .ncp-game-visual .ncp-r4-cover,#ncp-game-hub .ncp-game-visual .ncp-game-icon{opacity:1;filter:none;transform:none}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{background:rgba(255,255,255,.76);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);padding:7px 8px;border-radius:9px;box-sizing:border-box;text-shadow:none;box-shadow:0 2px 10px #14234612}

/* Compact game titles and image-only home cards. */
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{left:50%;right:auto;width:max-content;max-width:calc(100% - 24px);transform:translate(-50%,-50%);font-size:16px;font-weight:600;line-height:1.4;letter-spacing:-.3px;padding:6px 10px;border-radius:7px;word-break:keep-all;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;box-shadow:none}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body{padding:0}
.ncp-coupon-count{font-size:11px;font-weight:600;padding:4px 8px;border-radius:999px;box-shadow:none}
.ncp-game-cover-link{display:block}

/* Dense four-column mobile coupon grids. */
@media(max-width:600px){
.ncp-r4-game-list,.ncp-r4-latest-list,#ncp-game-hub .ncp-game-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.ncp-r4-game-list .ncp-r4-cover,#ncp-game-hub .ncp-game-icon-wrap{height:auto;aspect-ratio:1}
.ncp-r4-card,#ncp-game-hub .ncp-game-card{border-radius:10px}
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{top:56%;font-size:11px;line-height:1.3;max-width:calc(100% - 8px);padding:4px;border-radius:5px;letter-spacing:-.3px}
.ncp-coupon-count{top:4px;left:4px;font-size:9px;padding:2px 5px}
.ncp-r4-latest-list .ncp-r4-cover{height:auto;aspect-ratio:1;padding:6px}
.ncp-r4-latest-list .ncp-r4-card-body{padding:7px 5px}
.ncp-r4-latest-list h3{font-size:11px;line-height:1.45;margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
#ncp-game-hub .ncp-game-updated{font-size:10px;margin:6px 5px 8px}
}

/* Keep game names readable in narrow mobile cards. */
@media(max-width:600px){
.ncp-r4-game-list .ncp-game-visual .ncp-r4-card-body h3,#ncp-game-hub .ncp-game-visual .ncp-game-name{font-size:10px;line-height:1.35;word-break:normal;overflow-wrap:anywhere;-webkit-line-clamp:3;max-width:calc(100% - 6px);padding:4px 3px}
.ncp-r4-section-head h2{white-space:nowrap;flex-shrink:0}
.ncp-r4-section-head p{font-size:11px;text-align:right}
}

/* Twelve-item coupon pagination. */
.ncp-r4-pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:14px}.ncp-r4-pager span{font-size:12px;color:#65738a}.ncp-r4 .ncp-r4-pager button{width:44px;height:44px;min-height:44px;padding:0;font-size:21px;border-radius:50%;background:#edf3ff;color:#1858e9!important}.ncp-r4-pager button:disabled{opacity:.35;cursor:default}

/* Unified browse controls and animated coupon pages. */
.ncp-r4-section-head .ncp-r4-view-all{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;background:#f0f5ff;border:1px solid #e0e9fb;border-radius:999px;color:#2355c8;font-size:12px;font-weight:600;white-space:nowrap;transition:background .18s,box-shadow .18s}
.ncp-r4-view-all:after{content:'';width:6px;height:6px;border-top:1.5px solid currentColor;border-right:1.5px solid currentColor;transform:rotate(45deg)}
.ncp-r4-view-all:hover{background:#e5eeff;box-shadow:0 2px 8px #2355c812}
.ncp-r4-pager{gap:10px;margin-top:18px;padding:2px 0}.ncp-r4-pager span{min-width:44px;text-align:center;font-size:12px;font-weight:600;font-variant-numeric:tabular-nums;color:#67748a}
.ncp-r4 .ncp-r4-pager button{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;min-height:40px;border:1px solid #dce5f4;background:#fff;color:#254fc2!important;box-shadow:0 2px 5px #14234608;transition:background .18s,transform .18s,box-shadow .18s}
.ncp-r4 .ncp-r4-pager button:last-child:not(:disabled){background:#2457dc;border-color:#2457dc;color:#fff!important;box-shadow:0 3px 10px #2457dc22}
.ncp-r4-pager button:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 4px 12px #2457dc22}.ncp-r4 .ncp-r4-pager button:disabled{background:#f5f7fa;border-color:#edf0f5;color:#b4bfce!important;opacity:1;box-shadow:none}
.ncp-r4-pager button:focus-visible,.ncp-r4-view-all:focus-visible{outline:3px solid #8eb5ff;outline-offset:3px}

/* Game heart controls; configured initial values are separate from actual clicks. */
.ncp-game-heart-shell{position:relative;min-width:0}.ncp-game-heart-shell .ncp-game-card{height:100%;box-sizing:border-box}
.ncp-r4 .ncp-game-heart,#ncp-game-hub .ncp-game-heart{position:absolute;left:7px;top:117px;z-index:4;display:inline-flex;align-items:center;gap:4px;min-height:24px;padding:3px 7px;border:0;border-radius:999px;background:#ffffffeb;color:#e14b75!important;font-size:11px;font-weight:600;line-height:1;cursor:pointer;box-shadow:0 1px 5px #14234616}.ncp-game-heart span:first-child{font-size:17px}.ncp-game-heart[aria-pressed=true]{background:#ffedf3!important}.ncp-game-heart:disabled{cursor:default}
@media(max-width:600px){.ncp-r4 .ncp-game-heart,#ncp-game-hub .ncp-game-heart{top:auto;bottom:5px;left:4px;padding:3px 5px;min-height:20px;font-size:9px;gap:2px}.ncp-game-heart span:first-child{font-size:14px}#ncp-game-hub .ncp-game-heart{bottom:37px}}

/* Identical heart geometry for selected and unselected states. */
.ncp-game-heart .ncp-heart-icon{display:flex;align-items:center;justify-content:center;flex:0 0 14px;width:14px;height:14px;font-size:0!important}.ncp-heart-icon svg{display:block;width:14px;height:14px;overflow:visible}.ncp-heart-icon path{fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.ncp-game-heart[aria-pressed=true] .ncp-heart-icon path{fill:currentColor}.ncp-game-heart span:last-child{font-variant-numeric:tabular-nums;line-height:14px}
@media(max-width:600px){.ncp-game-heart .ncp-heart-icon{flex-basis:12px;width:12px;height:12px}.ncp-heart-icon svg{width:12px;height:12px}.ncp-game-heart span:last-child{line-height:12px}}

/* Game category image cards without the redundant footer. */
#ncp-game-hub .ncp-game-heart-shell .ncp-game-card{display:block}#ncp-game-hub .ncp-game-heart{top:auto;bottom:7px}
@media(max-width:600px){#ncp-game-hub .ncp-game-heart{bottom:5px}}

/* Shared brand mark: readable name plus the registered favicon. */
/* Home categories each occupy one paginated card row. */
#ncp-home-r4 .ncp-r4-row-shell{position:relative;overflow:hidden;padding:2px 0}
#ncp-home-r4 .ncp-r4-row-list{touch-action:pan-y;cursor:grab;user-select:none}
#ncp-home-r4 .ncp-r4-row-list.ncp-r4-dragging{cursor:grabbing}
#ncp-home-r4 .ncp-r4-row-arrows{position:absolute;inset:0;pointer-events:none}
#ncp-home-r4 .ncp-r4-row-arrows[hidden]{display:none}
#ncp-home-r4 .ncp-r4-row-arrows .ncp-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
#ncp-home-r4 .ncp-r4-row-arrows button{position:absolute;top:50%;transform:translateY(-50%);display:flex;align-items:center;justify-content:center;pointer-events:auto;width:44px;height:52px;min-height:44px;padding:0;background:#ffffffed;color:#2457dc!important;border:1px solid #dce5f4;border-radius:10px;box-shadow:0 2px 10px #14234620}
#ncp-home-r4 .ncp-r4-row-previous{left:0}
#ncp-home-r4 .ncp-r4-row-previous svg{transform:rotate(180deg)}
#ncp-home-r4 .ncp-r4-row-next{right:0}
#ncp-home-r4 .ncp-r4-row-arrows button:disabled{visibility:hidden;pointer-events:none}
#ncp-home-r4 .ncp-r4-row-arrows button{z-index:6;background:#2457dc;color:#fff!important;border-color:#2457dc;box-shadow:0 2px 8px #14234640}
#ncp-home-r4 .ncp-r4-double-chevron{display:flex;gap:0;align-items:center;justify-content:center;width:28px;height:24px}
#ncp-home-r4 .ncp-r4-double-chevron i{display:block;width:10px;height:10px;border-top:3px solid #fff;border-right:3px solid #fff;transform:rotate(45deg);box-sizing:content-box}
#ncp-home-r4 .ncp-r4-row-previous .ncp-r4-double-chevron{transform:rotate(180deg)}
#ncp-home-r4 .ncp-r4-section-head{margin:0 0 6px;align-items:center}
#ncp-home-r4 .ncp-r4-category-row{margin-bottom:20px}
#ncp-home-r4 .ncp-r4-category-title{display:inline-flex;align-items:center;gap:9px;color:#142346;font-size:inherit;font-weight:inherit}
#ncp-home-r4 .ncp-r4-category-title:after{content:'';display:block;width:7px;height:7px;border-top:2px solid currentColor;border-right:2px solid currentColor;transform:rotate(45deg)}
#ncp-home-r4 .ncp-r4-title-icon{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;color:#314969}
#ncp-home-r4 .ncp-r4-title-icon svg{display:block;width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8}
#ncp-home-r4 .ncp-r4-row-arrows button{width:36px;height:36px;min-height:36px;top:50%;border-radius:50%;background:#fff;color:#314969!important;border:1px solid #d6deea;box-shadow:0 2px 8px #14234618}
#ncp-home-r4 .ncp-r4-row-previous{left:6px}
#ncp-home-r4 .ncp-r4-row-next{right:6px}
#ncp-home-r4 .ncp-r4-double-chevron{width:18px;height:18px}
#ncp-home-r4 .ncp-r4-double-chevron i{width:7px;height:7px;border-color:#314969;border-width:2px; margin-left:-3px}
#ncp-home-r4 .ncp-r4-row-arrows button:hover{background:#eef3ff;border-color:#b9cbea}
@media(max-width:600px){#ncp-home-r4 .ncp-r4-row-arrows button{width:30px;height:30px;min-height:30px}#ncp-home-r4 .ncp-r4-title-icon{width:23px;height:23px}#ncp-home-r4 .ncp-r4-title-icon svg{width:21px;height:21px}}
#ncp-home-r4 .ncp-r4-category-row{margin-bottom:20px}
#ncp-home-r4 .ncp-r4-row-list{grid-template-rows:1fr}
#ncp-home-r4 .ncp-r4-status:empty{display:none}
#ncp-home-r4 .ncp-r4-category-row .ncp-r4-pager{margin-top:10px}
#ncp-home-r4 .ncp-r4-row-list .ncp-r4-card:not(.ncp-game-visual) h3{font-size:14px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
@media(max-width:600px){#ncp-home-r4 .ncp-r4-row-list .ncp-r4-card:not(.ncp-game-visual) .ncp-r4-cover{aspect-ratio:1;height:auto}#ncp-home-r4 .ncp-r4-row-list .ncp-r4-card:not(.ncp-game-visual) .ncp-r4-card-body{padding:7px 5px}#ncp-home-r4 .ncp-r4-row-list .ncp-r4-card:not(.ncp-game-visual) h3{font-size:11px}}
.ncp-r4 .ncp-r4-logo{display:inline-flex;align-items:center;gap:8px;flex-shrink:0;white-space:nowrap;font-size:24px;line-height:1.2;letter-spacing:-.6px}.ncp-r4 .ncp-r4-brand-icon{display:block;width:32px;height:32px;flex:0 0 32px;border-radius:8px;object-fit:contain}
@media(max-width:600px){.ncp-r4 .ncp-r4-logo{font-size:20px}}

/* Representative logo whitespace correction; all card labels use the shared game rules. */
#ncp-home-r4 .ncp-brand-visual .ncp-r4-cover[src*="-representative."],#ncp-game-hub .ncp-brand-visual .ncp-game-icon[src*="-representative."]{object-fit:contain;transform:translateY(var(--ncp-logo-shift,0%))}
/* All categories share the same bottom-left heart anchor. */
#ncp-home-r4 .ncp-game-heart,#ncp-game-hub .ncp-game-heart{top:auto;bottom:7px;left:7px}
@media(max-width:600px){#ncp-home-r4 .ncp-game-heart,#ncp-game-hub .ncp-game-heart{bottom:5px;left:4px}}
/* Keep feedback inside the button without changing coupon row height. */
[data-ncp-copy][data-ncp-copied='true']{background:#087f5b!important;color:#fff!important;border-color:#087f5b!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)}
[data-ncp-copy][data-ncp-copy-error='true']{background:#b42318!important;color:#fff!important}
.ncp-copy-state,.ncp-r3-copy-state{position:absolute!important;width:1px!important;height:1px!important;min-height:0!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;clip-path:inset(50%)!important;white-space:nowrap!important;border:0!important}
.ncp-detail-overview{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:20px;margin:0 0 24px;border:1px solid #dce5f3;border-radius:18px;background:#f6f9ff;font-family:Arial,'Noto Sans KR',sans-serif}
.post-body .ncp-detail-icon{width:64px!important;height:64px!important;object-fit:cover;border-radius:14px;margin:0!important}
.ncp-detail-info{flex:1;min-width:180px}.ncp-detail-info strong{font-size:23px;color:#172033}.ncp-detail-info p{margin:5px 0 0!important;font-size:14px;line-height:1.6;color:#52657e}
.ncp-detail-register{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 18px;border-radius:10px;background:#2457d6;color:#fff!important;text-decoration:none!important;font-size:14px;font-weight:700}
.ncp-detail-duplicate-heading,.ncp-detail-duplicate-media{display:none!important}
.ncp-detail-note{padding:14px 16px;background:#f8fafc;border-left:3px solid #94a3b8;font-size:14px!important;line-height:1.7}
/* AKKIGO compact related game grid */
.post-body .ncp-detail-related{margin-top:28px;padding:20px;border:1px solid #e1e8f2;border-radius:16px;background:#f7f9fd;font-family:Arial,'Noto Sans KR',sans-serif}
.post-body .ncp-detail-related h2{margin:0 0 18px!important;font-size:19px!important;font-weight:800;color:#172033!important}
.post-body .ncp-detail-related-list{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:12px}
.post-body .ncp-detail-related-list a{display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;padding:0;border:0;border-radius:10px;text-decoration:none!important;background:transparent;text-align:center;transition:transform .18s ease}
.post-body .ncp-detail-related-list a:hover{transform:translateY(-3px)}.post-body .ncp-detail-related-list a:focus-visible{outline:3px solid #2457d6;outline-offset:4px}
.post-body .ncp-related-visual{display:block;width:100%;max-width:80px;aspect-ratio:1;overflow:hidden;border-radius:16px;background:#e8eef9;box-shadow:0 3px 9px #17203318}
.post-body .ncp-related-visual img{display:block;width:100%!important;height:100%!important;max-width:none!important;object-fit:cover;margin:0!important;border-radius:0!important}
.post-body .ncp-related-placeholder{display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:800;color:#2457d6}
.post-body .ncp-detail-related-list strong{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;min-height:34px;font-size:12px!important;line-height:1.4!important;color:#172033!important;word-break:keep-all;overflow-wrap:anywhere}
.post-body .ncp-detail-related-list .ncp-related-count{display:block;font-size:12px!important;line-height:1.4;color:#2457d6!important;font-weight:800}
@media(max-width:700px){.post-body .ncp-detail-related-list{grid-template-columns:repeat(4,minmax(0,1fr));gap:18px 10px}.post-body .ncp-detail-related{padding:16px}}
@media(max-width:600px){.ncp-detail-overview{padding:16px;gap:12px}.ncp-detail-register{width:100%}.ncp-detail-info{min-width:0}.ncp-detail-info strong{font-size:20px}}
/* Scoped additions preserve the native Blogger article and search form. */
.ncp-r4,.ncp-r3,#ncp-game-hub{font-family:system-ui,-apple-system,'Segoe UI','Noto Sans KR',sans-serif}
.ncp-r4-search,.ncp-r3-search{position:relative}
.ncp-r4-hero picture{display:block;min-width:0}
.ncp-search-results{position:absolute;left:0;right:0;top:calc(100% + 8px);z-index:30;max-height:350px;overflow:auto;padding:6px;background:#fff;border:1px solid #dce5f4;border-radius:12px;box-shadow:0 12px 28px #14234620;text-align:left}
.ncp-search-results[hidden]{display:none}
.ncp-search-results a{display:block;padding:12px;border-radius:8px;color:#142346!important;text-decoration:none;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.ncp-search-results a:hover,.ncp-search-results a[aria-selected=true]{background:#edf3ff}
.ncp-search-note{display:block;padding:9px 12px;border-top:1px solid #edf1f7;font-size:11px;color:#66758a}
.ncp-r4-category svg{width:32px;height:32px;stroke-width:1.8}
.ncp-r4-game-list,.ncp-r4-latest-list{touch-action:pan-y}
.ncp-r4 .ncp-r4-pager button{min-width:44px;min-height:44px}
.ncp-r4 .ncp-r4-pager svg{width:20px;height:20px}
.ncp-game-heart .ncp-heart-icon svg{width:100%;height:100%}
.ncp-game-heart svg path{fill:none;stroke:currentColor}
.ncp-game-heart[aria-pressed=true] svg path{fill:currentColor}
@media(max-width:600px){.ncp-r4-hero picture{grid-row:1}.ncp-r4-category svg{width:28px;height:28px}.ncp-search-results a{font-size:13px}.ncp-r4-section-head>.ncp-r4-sub{font-size:11px}}
@media(prefers-reduced-motion:reduce){.ncp-r4-card,.ncp-r4-pager button,.ncp-r4-view-all{transition:none!important}.ncp-r4-card:hover{transform:none}}
.post-header time.ncp-post-updated{display:inline-block;font-family:system-ui,sans-serif;font-size:13px;font-weight:600;font-style:normal;color:#64748b;line-height:1.5}
/* Shared readable coupon typography; article-level legacy sizes must not shrink it. */
.post-body [data-ncp-article]{font-size:16px!important;line-height:1.75!important}
.post-body [data-ncp-article] p,.post-body [data-ncp-article] li{font-size:16px!important;line-height:1.75!important}
.post-body [data-ncp-article] h2{font-size:22px!important;line-height:1.4!important}
.post-body [data-ncp-article] h3{font-size:18px!important;line-height:1.5!important}
.post-body .ncp-detail-info p{font-size:16px!important;line-height:1.65!important}
.post-body [data-ncp-article] .ncp-source-list{font-size:14px!important}
.post-body [data-ncp-article] .ncp-code-card{height:auto!important;min-height:76px!important;padding:12px 8px!important;font-size:14px!important;box-sizing:border-box}
.post-body [data-ncp-article] .ncp-list-header{font-size:13px!important}
.post-body [data-ncp-article] .ncp-col-order,.post-body [data-ncp-article] .ncp-col-source,.post-body [data-ncp-article] .ncp-col-source a,.post-body [data-ncp-article] .ncp-col-expiry{font-weight:600!important;color:#233b60}
.post-body [data-ncp-article] .ncp-col-code,.post-body [data-ncp-article] .ncp-list-header,.post-body [data-ncp-article] .ncp-col-action button{font-weight:700!important}
.post-body [data-ncp-article] .ncp-col-source,.post-body [data-ncp-article] .ncp-col-expiry{font-size:14px!important;line-height:1.5!important;min-width:0;overflow-wrap:anywhere}
.post-body [data-ncp-article] .ncp-col-code{font-size:16px!important;line-height:1.5!important;min-width:0;overflow-wrap:anywhere}
.post-body [data-ncp-article] .ncp-col-action button{font-size:14px!important;min-height:44px!important;padding:8px 6px!important;border-radius:8px!important;line-height:1.3!important}
@media(max-width:600px){
  .post-body [data-ncp-article] .ncp-list-header{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;overflow:hidden!important;clip-path:inset(50%);white-space:nowrap}
  .post-body [data-ncp-article] .ncp-code-card{grid-template-columns:minmax(0,1fr) 96px!important;grid-template-areas:'code action' 'source expiry';gap:10px 8px!important;padding:14px 8px!important}
  .post-body [data-ncp-article] .ncp-col-order{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
  .post-body [data-ncp-article] .ncp-col-code{grid-area:code}
  .post-body [data-ncp-article] .ncp-col-action{grid-area:action;min-width:0}
  .post-body [data-ncp-article] .ncp-col-source{grid-area:source;font-size:13px!important}
  .post-body [data-ncp-article] .ncp-col-expiry{grid-area:expiry;font-size:13px!important}
}

.post-body [data-ncp-presentation] :is(.ncp-maple-nav,.ncp-nav){display:flex;gap:8px;padding:6px;background:#f1f5fd;border-radius:16px;flex-wrap:wrap}
.post-body [data-ncp-presentation] :is(.ncp-maple-nav,.ncp-nav) a{display:flex;align-items:center;justify-content:center;gap:6px;flex:1 1 auto;min-height:44px;padding:10px 14px;border:0;border-radius:11px;color:#233b60;background:#fff;font-weight:700;text-decoration:none;box-shadow:0 2px 5px #1837590d}
.post-body [data-ncp-presentation] :is(.ncp-maple-nav,.ncp-nav) a:first-child{background:#2155e8;color:white}
.post-body [data-ncp-presentation] :is(.ncp-maple-nav,.ncp-nav) a:hover{filter:brightness(.95)}
.post-body [data-ncp-presentation] summary{list-style:none;display:flex;justify-content:space-between;align-items:center;gap:12px;min-height:44px}
.post-body [data-ncp-presentation] summary::-webkit-details-marker{display:none}
.post-body [data-ncp-presentation] .ncp-maple-history summary::after{content:'';width:10px;height:10px;border-right:3px solid currentColor;border-bottom:3px solid currentColor;transform:rotate(45deg);transition:transform .18s;margin:0 6px 6px auto;flex-shrink:0}
.post-body [data-ncp-presentation] .ncp-maple-history summary span{margin-left:auto}
.post-body [data-ncp-presentation] .ncp-maple-history[open]>summary::after{transform:rotate(225deg)}
.post-body [data-ncp-presentation] section,.post-body [data-ncp-presentation] .ncp-brief{position:relative}
.post-body [data-ncp-presentation] .ncp-brief .ncp-maple-summary{padding-right:58px}
.post-body [data-ncp-presentation] .ncp-info{position:absolute;top:12px;right:12px;margin:0;color:#2155e8;z-index:3;border:0!important;padding:0!important;background:transparent!important}
.post-body [data-ncp-presentation] .ncp-info>summary{display:flex;justify-content:center;width:44px;height:44px;cursor:pointer;background:transparent;border:0!important}
.post-body [data-ncp-presentation] .ncp-info>div{position:absolute;right:0;top:44px;width:min(420px,calc(100vw - 64px));padding:16px;border:0;border-radius:12px;background:#edf3ff;box-shadow:0 8px 26px #18375926;line-height:1.65;color:#233b60}
.post-body [data-ncp-presentation] .ncp-compact-list .ncp-list-header,.post-body [data-ncp-presentation] .ncp-compact-list .ncp-code-card{grid-template-columns:46px 116px 108px minmax(0,1fr) 126px}
.post-body [data-ncp-presentation] .ncp-col-action{display:flex;gap:6px;align-items:center}
.post-body [data-ncp-presentation] .ncp-col-action .ncp-share{width:44px!important;min-width:44px;flex:0 0 44px;background:#edf3ff!important;color:#2155e8!important;display:flex;align-items:center;justify-content:center;padding:0!important}
.post-body [data-ncp-presentation] .ncp-col-action [data-ncp-copy]{flex:1;min-width:0}
@media(max-width:600px){.post-body [data-ncp-presentation] .ncp-compact-list .ncp-code-card{grid-template-columns:minmax(0,1fr) 126px!important}.post-body [data-ncp-presentation] .ncp-compact-list .ncp-list-header{grid-template-columns:26px 61px 63px minmax(0,1fr) 126px}}
.post-body [data-ncp-presentation] summary:focus-visible,.post-body [data-ncp-presentation] :is(.ncp-maple-nav,.ncp-nav) a:focus-visible{outline:3px solid #7298ff;outline-offset:3px}

/* R2: heading and icon share the same 44px line. Theme owns these rules. */
.post-body [data-ncp-presentation] section{display:grid!important;grid-template-columns:minmax(0,1fr) 44px;column-gap:8px}
.post-body [data-ncp-presentation] section>*{grid-column:1/-1;min-width:0}
.post-body [data-ncp-presentation] section>h2{grid-column:1;grid-row:1;margin:24px 0 12px!important;padding-right:0!important;min-height:44px;display:flex;align-items:center}
.post-body [data-ncp-presentation] section>.ncp-info{position:relative!important;grid-column:2;grid-row:1;align-self:center;top:auto!important;right:auto!important;margin:24px 0 12px!important}
.post-body [data-ncp-presentation] .ncp-brief{position:relative;padding-right:58px}
.post-body [data-ncp-presentation] .ncp-brief>.ncp-info{top:50%!important;right:8px!important;transform:translateY(-50%)}
.post-body [data-ncp-presentation] .ncp-info>summary{width:44px!important;height:44px!important;min-height:44px!important;padding:0!important}
.post-body [data-ncp-presentation] nav a{border:0!important;min-height:44px!important;font-weight:700!important}
.post-body [data-ncp-presentation] .ncp-list-header,.post-body [data-ncp-presentation] .ncp-code-card{grid-template-columns:46px 116px 108px minmax(0,1fr) 126px!important}
.post-body [data-ncp-presentation] .ncp-col-action{gap:6px!important}
.post-body [data-ncp-presentation] .ncp-col-action .ncp-share{min-width:44px!important;flex:0 0 44px!important;min-height:44px!important}
.post-body [data-ncp-presentation] .ncp-col-action [data-ncp-copy]{flex:1!important;min-width:0;min-height:44px!important}
.post-body [data-ncp-presentation] .ncp-list-more{border:0!important;padding:0!important;margin:0!important}
.post-body [data-ncp-presentation] .ncp-list-more>summary{display:flex;justify-content:center;align-items:center;gap:10px;min-height:44px;margin-top:8px;border-radius:10px;background:#edf3ff;color:#233b60;font-weight:700;cursor:pointer;list-style:none}
.post-body [data-ncp-presentation] .ncp-list-more>summary::after{content:'';width:9px;height:9px;border-right:3px solid currentColor;border-bottom:3px solid currentColor;transform:rotate(45deg)}
.post-body [data-ncp-presentation] .ncp-list-more[open]>summary::after{transform:rotate(225deg)}
.post-body [data-ncp-presentation] .ncp-list-more[open]{position:relative;padding-bottom:52px!important}
.post-body [data-ncp-presentation] .ncp-list-more[open]>summary{position:absolute;bottom:0;left:0;right:0;margin-top:8px}
@media(max-width:600px){.post-body [data-ncp-presentation] .ncp-code-card{grid-template-columns:minmax(0,1fr) 126px!important}}

/* Period R1: one renderer, no per-game CSS or date/source section splitting. */
.item-view .post-body>[data-ncp-feed-preview]{display:none!important}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-feed-preview{display:none!important}
.post-body [data-ncp-template="game-period-tabs-r1"]{color:#233b60;overflow-wrap:anywhere}
.post-body [data-ncp-template="game-period-tabs-r1"] section{padding:0 18px 18px;margin:22px 0;border:1px solid #dde5ee;border-radius:14px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-list-header{display:grid;padding:10px 6px;background:#eef3f8;border-bottom:2px solid #a8b9ca}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-code-card{display:grid;align-items:center;column-gap:8px;padding:12px 6px;border-bottom:1px solid #dde5ee;min-height:76px;height:auto;box-sizing:border-box}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-action button{height:44px;border:0;border-radius:9px;cursor:pointer;font-weight:700}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-copy{color:white;background:#294f80}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-action .ncp-copy-state:empty{display:none}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-code-status{display:block;font:600 12px/1.5 system-ui;color:#596b82;margin-top:4px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source{position:relative;display:flex;align-items:center;flex-wrap:wrap;gap:2px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source>.ncp-info{position:static!important;display:inline-block;transform:none;margin:0}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source>.ncp-info>summary{width:28px!important;height:28px!important;min-height:28px!important}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source>.ncp-info>summary svg{width:17px;height:17px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source>.ncp-info>div{top:100%;left:0;right:auto;z-index:8}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-info[open]{z-index:9}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-info>div{max-height:min(65vh,520px);overflow:auto;box-sizing:border-box}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-controls{display:grid;grid-template-columns:repeat(var(--ncp-period-count),minmax(0,1fr));gap:6px;border:0;padding:0;margin:18px 0;min-width:0}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option{display:contents}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>label{grid-row:1;display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:8px 2px;box-sizing:border-box;border-radius:10px;background:#edf3ff;font-weight:700;cursor:pointer;font-size:14px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>input{position:absolute;opacity:0;width:1px;height:1px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>input:checked+label{background:#2155e8;color:white}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>label>small{display:inline-flex;align-items:center;justify-content:center;min-width:28px;min-height:28px;padding:0 7px;box-sizing:border-box;border-radius:999px;background:#fff;color:#173b72;font-size:15px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>input:checked+label>small{background:#fff;color:#1746c7}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>input:focus-visible+label{outline:3px solid #7298ff;outline-offset:2px}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-panel{display:none!important;grid-column:1/-1;grid-row:2;margin:12px 0 0}
.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>input:checked+label+.ncp-period-panel{display:grid!important}
.post-body [data-ncp-template="game-period-tabs-r1"] figure{margin:0 0 16px}
.post-body [data-ncp-template="game-period-tabs-r1"] figure img{width:64px;height:64px;aspect-ratio:1/1;object-fit:contain;border-radius:14px}
.post-body [data-ncp-template="game-period-tabs-r1"] figure figcaption{display:none}
@media(max-width:600px){
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-period-option>label{flex-direction:column;gap:2px;font-size:12px;white-space:nowrap;padding:6px 2px}
 .post-body [data-ncp-template="game-period-tabs-r1"] section{padding:0 12px 12px}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-list-header,.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-order{display:none}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-code{grid-column:1;grid-row:1}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-action{grid-column:2;grid-row:1/4}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source{grid-column:1;grid-row:2}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-expiry{grid-column:1;grid-row:3}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source>.ncp-info>div{width:calc(100vw - 80px);max-width:420px}
}

/* Guides contain several headings: preserve normal document flow. */
.post-body [data-ncp-presentation] .ncp-coupon-guide{display:block!important}

/* Desktop tables share content-sized columns across headers and every row. */
@media(min-width:601px){
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-card-list{display:grid;grid-template-columns:38px max-content fit-content(240px) minmax(100px,1fr) 126px;column-gap:8px}
 .post-body [data-ncp-template="game-period-tabs-r1"] :is(.ncp-list-header,.ncp-code-card,.ncp-list-more){grid-column:1/-1;display:grid;grid-template-columns:subgrid!important;column-gap:8px!important}
 .post-body [data-ncp-template="game-period-tabs-r1"] :is(.ncp-list-header,.ncp-code-card){padding-left:8px!important;padding-right:8px!important}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-list-more>summary{grid-column:1/-1}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-source{flex-wrap:nowrap}
 .post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-expiry{max-width:240px;word-break:keep-all}
}

@media(min-width:601px){.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-list-more[open]::details-content{display:contents}.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-list-more:not([open])::details-content{display:none}}

/* Share remaining desktop space across source, expiry and coupon columns. */
@media(min-width:601px){.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-card-list{grid-template-columns:38px minmax(112px,1fr) minmax(132px,1fr) minmax(96px,1fr) 126px}.post-body [data-ncp-template="game-period-tabs-r1"] .ncp-col-expiry{max-width:none}}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

head.script:
//
window.ncpResolveGame=(function(){const known=["원신","승리의 여신: 니케","붕괴: 스타레일","명조:워더링 웨이브","포트블록스","킹샷","블루 아카이브","메이플 키우기","화이트아웃 서바이벌","브라운더스트2","트릭컬 리바이브","시바 모험단","컴투스프로야구V26","제우스: 오만의 신","Pokémon GO","로블록스","운빨존많겜","FC 모바일"];const resolve=function resolveGame(entry,knownNames=[]){
 const title=String(entry.title?.$t||entry.title||'').trim();
 const body=String(entry.content?.$t||entry.content||'');
 const explicit=body.match(/data-game-name=["']([^"']+)["']/)?.[1];
 const labels=(entry.category||[]).map(x=>x.term||x);
 const generic=new Set(['게임','쿠폰','교환코드','리딤코드','프로모션','할인코드','기프트코드','쿠폰코드']);
 const candidate=[...knownNames,...labels].filter(x=>x&&!generic.has(x)&&title.startsWith(x)).sort((a,b)=>b.length-a.length)[0];
 const name=explicit||candidate||title.split(/\s+(?:쿠폰|프로모션|리딤|교환|기프트|코드|할인)/)[0]||title;
 const explicitId=body.match(/data-game-id=["']([^"']+)["']/)?.[1];
 const articleKey=body.match(/data-ncp-article=["']([^"']+)["']/)?.[1];
 // Existing names are legacy primary keys: retain their votes and browser state.
 const legacy=knownNames.find(value=>value.replace(/\s/g,'')===name.replace(/\s/g,''));
 const id=legacy||explicitId||articleKey?.replace(/-\d{6}(?:.*)?$/,'')||name;
 return {id,name};
};return entry=>resolve(entry,known);})();
//

