// Optional adapter. No network, storage, page_view, URL, code or user identity is collected here.
(function(){
  if(window.ncpAnalyticsInstalled)return;
  window.ncpAnalyticsInstalled=true;
  const names=new Set(['coupon_copy','share','redeem_outbound']);
  document.addEventListener('click',event=>{
    const link=event.target.closest?.('a.ncp-detail-register,a[data-ncp-redeem]');
    if(!link||event.defaultPrevented)return;
    try{
      const target=new URL(link.href,location.href);
      if(target.protocol!=='https:'||target.origin===location.origin)return;
      window.dispatchEvent(new CustomEvent('ncp:action',{detail:{name:'redeem_outbound',method:'link',outcome:'click'}}));
    }catch{}
  });
  window.addEventListener('ncp:action',event=>{
    const detail=event.detail||{};
    if(!names.has(detail.name)||detail.outcome!==(detail.name==='redeem_outbound'?'click':'success'))return;
    // The site's consent controller must explicitly grant analytics; no inferred consent.
    if(window.ncpAnalyticsConsent!=='granted'||window.ncpAnalyticsEnabled!==true)return;
    if(window.ncpAnalyticsInternalTraffic===true||navigator.globalPrivacyControl===true)return;
    if(typeof window.gtag!=='function')return;
    // Disable inherited default page URL/title/referrer, which can contain user input.
    try{window.gtag('event',detail.name,{
      outcome:detail.name==='redeem_outbound'?'click':'success',
      method:detail.name==='redeem_outbound'?'link':detail.method==='native'?'native':'clipboard',
      page_location:location.origin+(/^\/\d{4}\/\d{2}\/[a-z0-9_-]+\.html$/i.test(location.pathname)?location.pathname:'/'),
      page_referrer:'',page_title:'',
      non_interaction:false
    });}catch{}
  });
})();

// AKKIGO persistent copy feedback: copying is not redemption confirmation.
(function(){
 const record=(name,method)=>{try{window.dispatchEvent(new CustomEvent('ncp:action',{detail:{name,method,outcome:'success'}}));}catch{}};
 const moreLabels=new WeakMap();
 document.addEventListener('toggle',event=>{
  const details=event.target;if(!details.matches?.('.ncp-list-more'))return;
  const summary=details.querySelector(':scope>summary');if(!summary)return;
  if(!moreLabels.has(summary))moreLabels.set(summary,{text:summary.textContent,label:summary.getAttribute('aria-label')});
  const original=moreLabels.get(summary);
  summary.textContent=details.open?'접기':original.text;
  if(original.label)summary.setAttribute('aria-label',details.open?original.label.replace(/나머지 .*개 보기$/,'목록 접기'):original.label);
 },true);
 const key=button=>'ncp-copied:'+location.pathname+':'+button.dataset.ncpCopy;
 const mark=button=>{delete button.dataset.ncpCopyError;button.dataset.ncpCopied='true';button.textContent='복사 완료';};
 const restore=()=>document.querySelectorAll('[data-ncp-copy]').forEach(button=>{try{if(localStorage.getItem(key(button))==='1')mark(button);}catch{}});
 restore();document.addEventListener('DOMContentLoaded',restore,{once:true});
 document.addEventListener('click',async event=>{
  const share=event.target.closest('[data-ncp-share]');
  if(share){
   event.preventDefault();event.stopImmediatePropagation();
   const code=share.dataset.ncpShare;const url=location.origin+location.pathname;
   const label=code+' 공유';const payload={title:document.title,text:code,url};
   const fallback=share.dataset.ncpShareFallback==='true';
   share.setAttribute('aria-label',label);share.title='공유';delete share.dataset.ncpShareError;
   const shareStatus=share.closest?.('.ncp-code-card')?.querySelector('[role="status"]');if(shareStatus)shareStatus.textContent='';
   share.disabled=true;
   try{
    if(!fallback&&navigator.share&&(!navigator.canShare||navigator.canShare(payload))){await navigator.share(payload);record('share','native');}
    else {await navigator.clipboard.writeText(code+'\n'+url);share.setAttribute('aria-label','공유 링크 복사 완료');share.title='공유 링크 복사 완료';delete share.dataset.ncpShareFallback;record('share','clipboard');}
   }catch(error){if(error.name!=='AbortError'){
    share.dataset.ncpShareError=error.name||'Error';share.dataset.ncpShareFallback='true';
    const message=fallback?'링크 복사 실패 · 다시 시도':'공유 링크 복사 · 다시 누르세요';
    share.setAttribute('aria-label',message);share.title=message;
    if(shareStatus)shareStatus.textContent=message;
   }}
   finally{share.disabled=false;}
   return;
  }
  const button=event.target.closest('[data-ncp-copy]');if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const scope=button.closest('.ncp-code-card,.ncp-coupon-card,.ncp-r3-card')||button.parentElement;
  const status=scope?.querySelector('.ncp-copy-state,[role="status"]');
  button.disabled=true;
  try{
   await navigator.clipboard.writeText(button.dataset.ncpCopy||'');
   record('coupon_copy','clipboard');
   mark(button);try{localStorage.setItem(key(button),'1');}catch{}
   if(status)status.textContent='코드를 복사했습니다.';
  }catch{
   button.textContent='복사 실패';button.dataset.ncpCopyError='true';
   if(status)status.textContent='복사하지 못했습니다. 코드를 직접 선택해 복사하세요.';
  }finally{button.disabled=false;}
 },true);
})();

